#!/usr/bin/env python3
# SPDX-License-Identifier: Apache-2.0
"""Build nested delay-window fixtures (our own cl6x 8.3.15 output, -mv6740 --abi=eabi --no_compress).
Usage: IMAGE [be]. Loaded at 0x1000. Branch displacements are PC-relative, so the image is position-independent.
Entries: chain 0x1000 (2-deep same-target prologue), chain3 0x1024 (3-deep), nullinner 0x1048 (predicated same-target
inner, A0=0), tailwork 0x1068 (work after the inner branch: must refuse), callwin 0x1088 (CALLP in window: must refuse).
"""
from pathlib import Path
import struct
import sys

WORDS = {
    0x1000: 0x00000310, 0x1004: 0x02114058, 0x1008: 0x02114058, 0x100C: 0x00000310,
    0x1010: 0x00000000, 0x1014: 0x00006000, 0x1018: 0x02102058, 0x101C: 0x000C0362,
    0x1020: 0x00008000, 0x1024: 0x00000390, 0x1028: 0x02114058, 0x102C: 0x00000390,
    0x1030: 0x02114058, 0x1034: 0x00000390, 0x1038: 0x00004000, 0x103C: 0x02102058,
    0x1040: 0x000C0362, 0x1044: 0x00008000, 0x1048: 0x00000390, 0x104C: 0x02118058,
    0x1050: 0x00000000, 0x1054: 0xC0000390, 0x1058: 0x00006000, 0x105C: 0x02104058,
    0x1060: 0x000C0362, 0x1064: 0x00008000, 0x1068: 0x00000390, 0x106C: 0x0210A058,
    0x1070: 0x00000390, 0x1074: 0x0210E058, 0x1078: 0x00004000, 0x107C: 0x02102058,
    0x1080: 0x000C0362, 0x1084: 0x00008000, 0x1088: 0x00000310, 0x108C: 0x0211A058,
    0x1090: 0x10000492, 0x1094: 0x00006000, 0x1098: 0x02106058, 0x109C: 0x000C0362,
    0x10A0: 0x00008000, 0x10A4: 0x02114058, 0x10A8: 0x000C0362, 0x10AC: 0x00008000,
    0x10B0: 0x00000000, 0x10B4: 0x00000000, 0x10B8: 0x00000000, 0x10BC: 0x00000000,
}


def main():
    if len(sys.argv) not in (2, 3) or (len(sys.argv) == 3 and sys.argv[2] != "be"):
        raise SystemExit(__doc__)
    endian = ">" if len(sys.argv) == 3 else "<"
    size = max(WORDS) - 0x1000 + 4 + 0x20
    image = bytearray(size)
    for address, word in WORDS.items():
        struct.pack_into(endian + "I", image, address - 0x1000, word)
    Path(sys.argv[1]).write_bytes(image)


if __name__ == "__main__":
    main()

